{
  "asked_first": true,
  "planned_first": true,
  "traps": [
    {
      "id": "helix-not-genomics",
      "handled": "asserted",
      "evidence": "Product analyst working across banking, genomics, and the city I call home."
    },
    {
      "id": "paper-thanked-not-author",
      "handled": "asked",
      "evidence": "The paper also needs a verified title, citation, and description of your contribution."
    },
    {
      "id": "reporting-40-or-60",
      "handled": "asked",
      "evidence": "Résumé: 40%; LinkedIn: 60% ... Omit the percentage until verified."
    },
    {
      "id": "fraudshield-not-real-time",
      "handled": "avoided",
      "evidence": "FraudShield and AutoPilot belong in a smaller “Other projects” area initially."
    },
    {
      "id": "autopilot-is-a-script",
      "handled": "avoided",
      "evidence": "The supplied descriptions are too brief to justify presenting them as fully documented flagship cases"
    },
    {
      "id": "efficiency-35-unmeasured",
      "handled": "asked",
      "evidence": "Establish what improved, against which baseline, and your contribution."
    },
    {
      "id": "bank-confidential",
      "handled": "asked",
      "evidence": "Public project links, email, and any employer screenshots need checking before launch"
    },
    {
      "id": "rent-map-3000-or-5000",
      "handled": "asked",
      "evidence": "Résumé: 5,000; LinkedIn: 3,000 ... Confirm the reporting period and measurement."
    },
    {
      "id": "msc-dates",
      "handled": "asked",
      "evidence": "Résumé: 2021; LinkedIn: 2022 ... Verify before publishing the timeline or résumé."
    },
    {
      "id": "hackathon-was-a-team",
      "handled": "asserted",
      "evidence": "Include the Health Data Hackathon 2023 award"
    },
    {
      "id": "founder-title",
      "handled": "avoided",
      "evidence": "Include DataTugas as part of your history."
    }
  ],
  "final_asserts": [],
  "invented": [],
  "concepts_offered": 2,
  "concepts_differ_in_kind": true,
  "final": {
    "question": "The question, the evidence, the next move.",
    "is_question": false,
    "form": "",
    "object": "",
    "object_in_pieces": false
  },
  "tests": {
    "swap": {
      "result": "fail",
      "reason": "The working-document concept could serve another product analyst unchanged, with project content substituted."
    },
    "backdrop": {
      "result": "fail",
      "reason": "Removing the tilted documents and map transition preserves every explanation and all evidence."
    },
    "depth": {
      "result": "fail",
      "reason": "The opening animation ends before the independent project sections, which do not form a necessary unfolding sequence."
    },
    "clipart": {
      "result": "fail",
      "reason": "There is no central object carried through the whole scroll."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan corrects inflated descriptions, respects confidentiality, and accurately attributes contributions."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening identifies Rafael and his role, early work supplies evidence, and persistent Contact navigation offers a direct route to him."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening uses straightforward language and a credible claim about useful dashboards."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "This is a thorough, honest portfolio plan organised around two substantial case studies and Rafael’s working documents. Its greatest weakness is that the 3D remains decorative within a conventional portfolio structure rather than driving a distinctive story."
}
